/*
 * <linux/types.h>: the kernel's fixed-size integer types. The structures of the device headers use
 * them, so a field is exactly as wide as the kernel expects whatever the compiler: __u32 is an
 * unsigned 32-bit integer, __s16 a signed 16-bit one.
 *
 * Part of the x86 Runtime library, written for the editor in the shape of Linux's own header: the
 * same names, values and layouts, with only what the editor's devices use.
 *
 * Generated by scripts/sim-header/generate.mjs from scripts/sim-header/deviceTable.mjs. Do not edit
 * it: regenerate it.
 */
#ifndef _LINUX_TYPES_H
#define _LINUX_TYPES_H

#if !defined(__x86_64__)
#error "This <linux/types.h> is the x86 one, included in a compilation for another Target"
#endif

typedef signed char __s8;
typedef unsigned char __u8;
typedef short __s16;
typedef unsigned short __u16;
typedef int __s32;
typedef unsigned int __u32;
typedef long long __s64;
typedef unsigned long long __u64;

#endif
